  // DES-HOUR 21% VAT, PRINT-A4 9% VAT, should have 2 entries sorted by rate descending
  assert.equal(report.length, 2);
  assert.equal(report[0].rate, 21); // Higher rate first
  assert.equal(report[0].base, 8500); // DES-HOUR
