import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty list when no invoices overdue', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET30',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  // Due date is 2026-11-06, check as of 2026-10-31 (not overdue yet)
  const report = overdueInvoices([issued], '2026-10-31');
  assert.equal(report.length, 0);
});

test('overdueInvoices includes overdue invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  // Due date is 2026-10-21, check as of 2026-10-25 (4 days overdue)
  const report = overdueInvoices([issued], '2026-10-25');
  assert.equal(report.length, 1);
  assert.equal(report[0].number, 'INV-2026-0001');
  assert.equal(report[0].customerId, 'C-003');
  assert.equal(report[0].dueDate, '2026-10-21');
  assert.equal(report[0].daysOverdue, 4);
  assert.equal(report[0].due, 145200);
});

test('overdueInvoices excludes invoices not yet due', () => {
