  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r3.ok, true);
  const draft2 = r3.value;

  const r4 = issueInvoice(draft2, ['INV-2026-0001']);
  assert.equal(r4.ok, true);
  const issued2 = r4.value; // Due 2026-10-24

  // Check as of 2026-10-31: both overdue
  const report = overdueInvoices([issued2, issued1], '2026-10-31');
  assert.equal(report.length, 2);
  assert.equal(report[0].number, 'INV-2026-0001'); // 16 days overdue (due 2026-10-15)
  assert.equal(report[0].daysOverdue, 16);
  assert.equal(report[1].number, 'INV-2026-0002'); // 7 days overdue (due 2026-10-24)
