test('overdueInvoices handles multiple customers', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r1.ok, true);
  const draft1 = r1.value;

  const r2 = issueInvoice(draft1, []);
  assert.equal(r2.ok, true);
  const issued1 = r2.value; // C-003, due 2026-10-21

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r3.ok, true);
  const draft2 = r3.value;

  const r4 = issueInvoice(draft2, ['INV-2026-0001']);
  assert.equal(r4.ok, true);
  const issued2 = r4.value; // C-001, due 2026-10-19

  const report = overdueInvoices([issued1, issued2], '2026-10-25');
  assert.equal(report.length, 2);
  assert.equal(report[0].customerId, 'C-001'); // More overdue (6 days vs 4 days)
  assert.equal(report[1].customerId, 'C-003');
});

