test('lateFee charges for one day overdue', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value; // Due 2026-10-21

  // One day after due date
  const fee = lateFee(issued, '2026-10-22');
  // Amount due: 8500 + 1785 = 10285 cents
  // Rate: 0.04% per day = 0.0004
  // Fee: 10285 * 0.0004 * 1 = 4.114 → rounds to 4 cents
  assert.equal(fee, 4);
});

